package com.projecteden.village.domain;
import java.time.LocalDateTime;import com.projecteden.character.domain.Character;import jakarta.persistence.*;
@Entity@Table(name="village_histories")public class VillageHistory{
	@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="character_id",nullable=false)private Character character;@Enumerated(EnumType.STRING)@Column(nullable=false)private VillageHistoryType historyType;@Enumerated(EnumType.STRING)private VillageCategory category;@Enumerated(EnumType.STRING)private VillageChangeType changeType;@Column(nullable=false)private String message;@Column(nullable=false)private LocalDateTime createdAt;
	protected VillageHistory(){}private VillageHistory(Character character,VillageHistoryType type,VillageCategory category,VillageChangeType changeType,String message,LocalDateTime now){this.character=character;this.historyType=type;this.category=category;this.changeType=changeType;this.message=message;this.createdAt=now;}public static VillageHistory create(Character character,VillageHistoryType type,VillageCategory category,VillageChangeType changeType,String message,LocalDateTime now){return new VillageHistory(character,type,category,changeType,message,now);}
	public Long getId(){return id;}public Character getCharacter(){return character;}public VillageHistoryType getHistoryType(){return historyType;}public VillageCategory getCategory(){return category;}public VillageChangeType getChangeType(){return changeType;}public String getMessage(){return message;}public LocalDateTime getCreatedAt(){return createdAt;}
}
